update public.fields set verification_status='verified_against_standard', verification_quote='These four types of content are intended to be mutually exclusive and add up to represent 100 % of the resource inflow (see Figure A.1). The first three types (recycled, reused and virgin, renewable content) are considered as circular; whereas the fourth type (virgin, non-renewable content) is the remaining portion that is from a non-circular source. The non-circular (linear) inflow can be calculated by subtracting the circular inflows from 100 %. — printed p.31', verification_note='VA-verified 2026-09-08 (§A.2.1, printed p.31 — this is the printed basis of the 100 % balance gate CR-014) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='df15b536-271b-40e0-aa38-b605461c2ce6' and verification_status not in ('verified_against_standard','corrected');
-- ISO-59020-06.tLP_X
