-- ISO-59020-08.system_breakdown_done
update public.fields set verification_status='verified_against_standard', verification_quote='To enable a systematic data acquisition, and to provide transparency to the acquired data, it is recommended that the system in focus is subdivided into its elementary components for which data acquisition can be practically executed, such as the identification of data sources for general inflows and outflows. — printed p.20', verification_note='VA-verified 2026-09-08 (§7.6.1.2 Step A, printed p.20 — printed modal is "it is recommended that", i.e. a recommendation; gate CR-026 is correctly a warn) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='e1a20088-49c5-4948-8ca6-c4fd7c6a7284' and verification_status not in ('verified_against_standard','corrected');
-- ISO-59020-08.data_category
update public.fields set verification_status='verified_against_standard', verification_quote='— be categorized as foreground or background, primary or secondary, specific or generic (secondary and generic data should be conservatively applied and not overstate the circularity); — printed p.21', verification_note='VA-verified 2026-09-08 (§7.6.2, printed p.21 — the six enum values are the three printed dichotomies) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='0224960d-b232-4177-a193-b068fea48424' and verification_status not in ('verified_against_standard','corrected');
