-- ISO-59020-08.data_completeness_checked
update public.fields set verification_status='verified_against_standard', verification_quote='Checking whether the information is complete includes, but is not limited to, checking whether for each acquired data item and each selected indicator: | — all data requirements presented under 7.6.2 are met; — printed p.21', verification_note='VA-verified 2026-09-08 (§7.6.1.6 Step E, printed p.21) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='872c83ff-e004-4285-acde-b9322bac110f' and verification_status not in ('verified_against_standard','corrected');
-- ISO-59020-08.data_normalized
update public.fields set verification_status='verified_against_standard', verification_quote='Data acquired should be balanced and normalized to the common denominator for the system in focus, such as "per provided function", "per product lifetime" or "per yearly production". All these transformations should be documented. — printed p.21', verification_note='VA-verified 2026-09-08 (§7.6.1.5 Step D, printed p.21) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='d02d2034-5012-447b-b43e-fa4783a261fd' and verification_status not in ('verified_against_standard','corrected');
-- ISO-59020-08.data_traceability
update public.fields set verification_status='verified_against_standard', verification_quote='data traceability ability of data to be tracked to original and verifiable sources | Note 2 to entry: ISO 14033:2019 provides a framework both for how to achieve data traceability as well as how to audit and verify the level to which data traceability has been achieved. — printed p.5', verification_note='VA-verified 2026-09-08 (§3.3.16, printed p.5 — the framework itself lives in ISO 14033, which is not in the library, so the "how" is NR; the definition and the pointer are VA) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='82123c62-3f11-438d-8252-0d4c0192f76f' and verification_status not in ('verified_against_standard','corrected');
-- ISO-59020-08.documentation_complete
