-- ISO-59020-08.allocation_method
update public.fields set verification_status='verified_against_standard', verification_quote='allocation partitioning of the inflows and outflows of a process or a system between the system in focus (3.2.2) and one or more other systems | 1) allocation methods used to separate the system in focus from the wider system, cut-off limits and any other choices relevant to setting system boundaries; — printed pp.4/23', verification_note='VA-verified 2026-09-08 (§3.3.15 (printed p.4) / §7.7 c) 1) (printed p.23)) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='a690bee8-bdc2-4b36-872b-bfd9e95ec431' and verification_status not in ('verified_against_standard','corrected');
