-- ISO-59020-09.criteria_review_done
update public.fields set verification_status='verified_against_standard', verification_quote='In conducting the assessment, the organization is required to review the application of: | a) the circular economy principles in ISO 59004; | b) the principles of measuring and assessing circularity in Clause 4; | c) the core circularity indicators of Clause 7, Table 3 and guidance from Annex A. — printed p.23', verification_note='VA-verified 2026-09-08 (§8.1, printed p.23 — "is required to" is a shall-equivalent under ISO/IEC Directives Part 2, so the block severity of gate CR-031 is defensible even though the word "shall" does not appear) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='e5ec7082-d791-450a-a2bc-631b8ae5d755' and verification_status not in ('verified_against_standard','corrected');
-- ISO-59020-09.complementary_method
update public.fields set verification_status='verified_against_standard', verification_quote='complementary method method, approach or standard that is used together with circularity measurement (3.3.2) to provide a circularity assessment (3.3.3) — printed p.3', verification_note='VA-verified 2026-09-08 (§3.3.7, printed p.3; examples are in Annex C, which is INFORMATIVE, and the field is correctly optional) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='a9ea4f4a-0281-4021-80af-3dc7b3267ef9' and verification_status not in ('verified_against_standard','corrected');
-- ISO-59020-09.value_impact_assessed
update public.fields set verification_status='verified_against_standard', verification_quote='While assessing the circularity performance, a broad perspective of sustainability should be considered to maximize the contribution to sustainable development. — printed p.25', verification_note='VA-verified 2026-09-08 (§8.4.1, printed p.25) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='86c433ec-8cf8-46ee-82b3-bd64b548b8ee' and verification_status not in ('verified_against_standard','corrected');
-- ISO-59020-09.interested_parties_consulted
update public.fields set verification_status='verified_against_standard', verification_quote='In consulting interested parties, users and target audiences, the following needs and requirements should be reviewed: — printed p.29', verification_note='VA-verified 2026-09-08 (§8.5 Step 3, printed p.29) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='cc769ef2-1d50-44b4-b5ed-1de679fca71a' and verification_status not in ('verified_against_standard','corrected');
-- ISO-59020-09.report_transparency
update public.fields set verification_status='verified_against_standard', verification_quote='In documenting the circularity performance outcome of the core circularity indicators of Annex A and other indicators (see Annex B), the organization should include the best available information to summarize all resource inflows and outflows including non-circular flows of the system in focus. — printed p.29', verification_note='VA-verified 2026-09-08 (§8.6.1 Step 4, printed p.29) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='74f7357e-19ef-4903-9571-19b481b56855' and verification_status not in ('verified_against_standard','corrected');
-- ISO-59020-09.information_verifiable
update public.fields set verification_status='verified_against_standard', verification_quote='Verifiability of all data documentation is a key criterion to ensure transparency. — printed p.29', verification_note='VA-verified 2026-09-08 (§8.6.2, printed p.29) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='4a082e0b-7f9e-4700-92b8-a7638792d4c6' and verification_status not in ('verified_against_standard','corrected');
-- ISO-59020-09.hazardous_substances_reported
update public.fields set verification_status='verified_against_standard', verification_quote='Organizations responsible for recycling, recovery and recirculation should request information on the chemical composition of materials received or collected in order to ensure correct handling and treatment and lower the risk of mismanagement. — printed p.30', verification_note='VA-verified 2026-09-08 (§8.6.4, printed p.30 — printed modal "should", and the field is correctly optional) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='eb510e9a-7d6b-47a1-afb8-294f01bd228d' and verification_status not in ('verified_against_standard','corrected');

-- ============================================================================
-- B. APP-METADATA EXEMPTION - 1 row (2026-08-01 metadata ruling)
-- ============================================================================
-- ISO-59020-01.standard_edition ("Norm-Ausgabe" / edition of ISO 59020 applied). The identifier
-- ISO 59020:2024, First edition, 2024-05 IS printed on the title page, but the title page is a
-- publisher colophon set in columns, not a normative sentence, and ISO 59020 nowhere defines a
-- field obliging a user to record which edition was applied. Recording it is app/project workflow
-- metadata, so it is exempted rather than given a manufactured quote.
update public.fields set verification_status='inferred_from_worksheet', verification_note='VA-pass 2026-09-08: app/project metadata - the guideline does not define this field; exempt per the 2026-08-01 metadata ruling. (The string "ISO 59020 / First edition / 2024-05" appears on the unnumbered title page, PDF p.1, as column-set colophon text, not as a requirement.)', verified_at=now() where id in ('3dd50c3e-d200-41c2-8ba0-72d43b934f0f') and verification_status not in ('verified_against_standard','corrected');

-- ============================================================================
-- C. EQUATIONS - 13 rows, all 13 printed formulae of normative Annex A
-- ============================================================================
-- Formula (A.1)
update public.equations set verification_status='verified_against_standard', verification_quote='The calculation of the circularity indicator is performed by applying Formula (A.1): | %REUI(X) is the average reused content of an inflow (X), in %; mREUI(X) is the mass of reused components and products of an inflow (X), in kg or other mass unit; mTI(X) is the mass of total input material of an inflow (X), in kg or other mass unit. — printed p.33', verification_note='VA-verified 2026-09-08 (§A.2.2 (Formula A.1), printed p.33 — dimension check: kg / kg x 100 = %, matches the unit of pct_REUI_X. Mandatory core indicator per Table 3) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='62e2cbfd-f530-4450-a9b7-1982fa1f955b' and verification_status <> 'verified_against_standard';
-- Formula (A.2)
update public.equations set verification_status='verified_against_standard', verification_quote='The calculation of the circularity indicator is performed by applying Formula (A.2): | %RECI(X) is the average recycled content of an inflow (X), in %; mRECI(X) is the mass of recycled material of an inflow (X), in kg or other mass unit; mTI(X) is the mass of total input material of an inflow (X), in kg or other mass unit. — printed p.33', verification_note='VA-verified 2026-09-08 (§A.2.3 (Formula A.2), printed p.33 — dimension check: kg / kg x 100 = %, matches the unit of pct_RECI_X. Mandatory core indicator per Table 3) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='3d0e7b99-83ba-447d-9101-df3ab06c11c2' and verification_status <> 'verified_against_standard';
-- Formula (A.3)
update public.equations set verification_status='verified_against_standard', verification_quote='The calculation of the circularity indicator is performed by applying Formula (A.3): | PRENI(X) is the average renewable content of an inflow (X), in %; mRENI(X) is the mass of renewable material of an inflow (X), in kg or other mass unit; mTI(X) is the mass of total input material of an inflow (X), in kg or other mass unitg. — printed p.34', verification_note='VA-verified 2026-09-08 (§A.2.4 (Formula A.3), printed p.34 — dimension check: kg / kg x 100 = %, matches the unit of pct_RENI_X. The trailing "unitg" is a typographical slip in the printed where-list and is quoted verbatim. Mandatory core indicator per Table 3) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='77f9ac60-2373-41f5-aa09-071b9e311ff2' and verification_status <> 'verified_against_standard';
-- Formula (A.4)
update public.equations set verification_status='verified_against_standard', verification_quote='The calculation of the circularity indicator is performed by applying Formula (A.4): | RLP(X) is the lifetime ratio of a product or material (X); it is dimensionless; tLP(X) is the lifetime of a product or material (X), in, for example, years; tIALP(X) is the industry average lifetime of a product or material (X), in, for example, years; — printed p.36', verification_note='VA-verified 2026-09-08 (§A.3.2 (Formula A.4), printed p.36 — dimension check: time / time = dimensionless, matches RLP_X having no unit. Optional core indicator per Table 3; §A.3.1 (printed p.35) states it "is not mandatory to calculate". This is the only equation whose output no gate consumes (see the STAGED file)) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='36c2e3ea-1c39-458c-b1ab-0568b515e4ec' and verification_status <> 'verified_against_standard';
-- Formula (A.5)
update public.equations set verification_status='verified_against_standard', verification_quote='The calculation of the circularity indicator is performed by applying Formula (A.5): | PREUO(X) is the actual reused products and components derived from outflow (X), in %; mREUO(X) is the mass of outflow (X) that is reused, in kg or other mass unit; mTO(X) is the total mass of outflow (X), in kg or other mass unit. — printed pp.36-37', verification_note='VA-verified 2026-09-08 (§A.3.3 (Formula A.5), printed pp.36-37 (the formula on p.36, its where-list on p.37) — dimension check: kg / kg x 100 = %, matches the unit of pct_REUO_X. Mandatory core indicator per Table 3) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='b96ecbfd-5f01-4c9b-af8a-864ebe15982a' and verification_status <> 'verified_against_standard';
-- Formula (A.6)
update public.equations set verification_status='verified_against_standard', verification_quote='The calculation of the circularity indicator is performed by applying Formula (A.6): | PRECO(X) is the per cent actual recycled material derived from outflow (X), in %; mRECO(X) is the mass of recycled material derived from outflow (X), in kg or other mass unit; mTO(X) is the total mass of outflow (X), in kg or other mass unit. — printed p.37', verification_note='VA-verified 2026-09-08 (§A.3.4 (Formula A.6), printed p.37 — dimension check: kg / kg x 100 = %, matches the unit of pct_RECO_X. Mandatory core indicator per Table 3) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='1e0f3bf1-e489-4678-9fa3-84394512a64c' and verification_status <> 'verified_against_standard';
-- Formula (A.7)
update public.equations set verification_status='verified_against_standard', verification_quote='The calculation of the circularity indicator is performed by applying Formula (A.7): | PRENO(X) is the per cent actual recirculation of outflow (X) in the biological cycle, in %; mRENO(X) is the mass of outflow (X) that is renewable recirculation, in kg or other mass unit; mTO(X) is the total mass of outflow (X), in kg or other mass unit. — printed p.38', verification_note='VA-verified 2026-09-08 (§A.3.5 (Formula A.7), printed p.38 — dimension check: kg / kg x 100 = %, matches the unit of pct_RENO_X. Mandatory core indicator per Table 3) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='3fc5b480-968f-4176-bd3b-6eb91f1f6f3b' and verification_status <> 'verified_against_standard';
-- Formula (A.8)
update public.equations set verification_status='verified_against_standard', verification_quote='The calculation of the circularity indicator is performed by applying Formula (A.8): | PECONRE(X) is the average energy (X) consumed that is renewable energy, in %; EIRENE(X) is the renewable energy (X) inflow, in MJ (or in kWh); EORENE(X) is the renewable energy (X) outflow, in MJ (or in kWh); EITE(X) is the total energy (X) inflow, in MJ (or in kWh); EOTE(X) is the total energy (X) outflow, in MJ (or in kWh). — printed p.39', verification_note='VA-verified 2026-09-08 (§A.4.2 (Formula A.8), printed p.39 — dimension check: (MJ - MJ) / (MJ - MJ) x 100 = %, matches the unit of pct_ECONRE_X; all four inputs carry the same encoded unit MJ, so the two differences are dimensionally valid. Optional core indicator per Table 3. The printed denominator can be zero when total inflow equals total outflow; the encoding has no guard for that) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='16e117aa-9d53-4f91-8323-4cb016a18a3d' and verification_status <> 'verified_against_standard';
-- Formula (A.9)
update public.equations set verification_status='verified_against_standard', verification_quote='The calculation of the circularity indicator is performed by applying Formula (A.9): | PCWW is the average water withdrawal from circular sources, in %; VCIW is the volume of water inflow from circular sources, in m3/year; VAIW is the volume of water inflow from all sources, in m3/year. — printed p.41', verification_note='VA-verified 2026-09-08 (§A.5.2 (Formula A.9), printed p.41 — dimension check: (m3/year) / (m3/year) x 100 = %, matches the unit of pct_CWW. Optional core indicator per Table 3) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='c724b258-9a2a-47b4-99b2-7907a0b006dd' and verification_status <> 'verified_against_standard';
-- Formula (A.10)
update public.equations set verification_status='verified_against_standard', verification_quote='The calculation of the circularity indicator is performed by applying Formula (A.10): | PCDW is the average circular water discharges, in %; VCDW is the volume of circular water discharges, in m3/year; VAIW is the volume of water inflow from all sources, in m3/year. — printed p.41', verification_note='VA-verified 2026-09-08 (§A.5.3 (Formula A.10), printed p.41 — dimension check: (m3/year) / (m3/year) x 100 = %, matches the unit of pct_CDW. The denominator is the water INFLOW from all sources, not the discharge total; that is what is printed, and Table 3 describes it the same way) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='55e9a431-e000-4ee9-914c-1fce534ea092' and verification_status <> 'verified_against_standard';
-- Formula (A.11)
update public.equations set verification_status='verified_against_standard', verification_quote='The calculation of the circularity indicator is performed by applying Formula (A.11): | is the ratio (on-site or internal) of water reuse or recirculation; it is dimensionless and | represents the amount of water recycled or reused within the facility after it has been | contained and adequately treated for reuse, as needed; | is the total water consumed in all processes and operations within the facility, in m3 per year; typically, the water used in a process or operation is the amount of water entering the process; | is the total water withdrawn from all external sources, in m3 per year; an external source is one from a local supply and not provided by internal processes or operations. — printed p.42', verification_note='VA-verified 2026-09-08 (§A.5.4 (Formula A.11), printed p.42 — dimension check: (m3/year) / (m3/year) = dimensionless, matches RWRR having no unit. In the printed where-list the symbol column (RWRR, VTWU, VTWW) is set beside the definition column, so the definitions are quoted as separate runs. §A.5.4 (printed p.41) states the ratio "will exceed 1,0 when water is reused or recirculated within the facility". Optional core indicator per Table 3) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='7e69300e-af43-40b2-9f75-ef773d9ffed7' and verification_status <> 'verified_against_standard';
-- Formula (A.12)
update public.equations set verification_status='verified_against_standard', verification_quote='The calculation of the circularity indicator is performed by applying Formula (A.12): | RMP is the MP ratio, in monetary units per kg (e.g. $/kg, €/kg); C is the total revenue generated in monetary units (e.g. $, €); D is the total mass of all linear resource inflows, in kg or other mass unit. — printed p.43', verification_note='VA-verified 2026-09-08 (§A.6.2 (Formula A.12), printed p.43 — dimension check: monetary unit / kg = monetary unit per kg, matches the encoded EUR/kg. Optional core indicator per Table 3) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='e3364b07-c567-4740-882c-d87e0e636a94' and verification_status <> 'verified_against_standard';
-- Formula (A.13)
update public.equations set verification_status='verified_against_standard', verification_quote='The calculation of the circularity indicator is performed by applying Formula (A.13): | IRII is the RII, expressed as a ratio; E is the rate of variation of resource inflow consumption (mass) per unit time; it is dimensionless; F is the rate of variation of GDP per unit time; it is dimensionless. — printed p.43', verification_note='VA-verified 2026-09-08 (§A.6.3 (Formula A.13), printed p.43 — dimension check: dimensionless / dimensionless = dimensionless ratio, matches IRII having no unit. Optional core indicator per Table 3) [VA · ISO 59020:2024 published First edition, PDF text layer]', verified_at=now() where id='fc67093c-8d64-4854-882e-a2f621059041' and verification_status <> 'verified_against_standard';
